"use client"

import { useId, useLayoutEffect, useRef, useState } from "react"
import type { PointerEvent } from "react"
import { motion, useReducedMotion } from "motion/react"

import { cn } from "@/lib/utils"

/* Scrub line: the large line a small one opens into (2026-11-10, out of KPI Card Row's
   large view, Market Shelf's open tile and Watchlist Stack's open row, which each needed
   the same thing). It fills the width it is given and draws at that real width, so its
   strokes and its text keep their size (nothing is stretched as a picture).

   What it draws, in the library's one chart language:
   · the line, drawn on once over 0.5s on the house expo-out, then held; it steps back to
     45% while a point is read
   · named levels (a high, a low, an open) as hairlines across the plot with their figure
     and name on the right axis, 9px; a `guide` level is dashed
   · marked points (the high, the low) as dots on the line, up as the draw lands
   · the pointed point: a rule and a dot. The reading itself is the host's: `hi` is the
     pointed index and `onHi` hears it, so the figure the small line wrote into keeps
     being the one place a value is read
   · optional names along the bottom axis, thinned to what the width holds, ends kept
   It is built from spans, so it can sit inside a button.
   Reduced motion: no draw, the marks are there at once.
   Formulas: x = place in the series ÷ (points − 1) × width; y from the series' own
   lowest and highest; a level sits at its own value on that scale. */

const EASE = [0.16, 1, 0.3, 1] as const
/** room above the highest and under the lowest point, for the round caps and the dots */
const TOP = 8
const BOT = 8
/** room at each end of the line, so a dot on the first or last point is whole */
const SIDE = 4
/** the least two axis figures keep between them */
const LEVEL_GAP = 12
/** the room one bottom axis name needs */
const TICK_ROOM = 58

const clamp = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, v))

export interface ScrubLineLevel {
  /** what the level is called on the axis: High, Low, Open */
  name: string
  value: number
  /** a dashed guide across the plot (a reference such as the open) */
  guide?: boolean
}

export function ScrubLine({
  data,
  format,
  hi,
  onHi,
  levels = [],
  marks = [],
  axis,
  stroke = "var(--foreground)",
  fill = false,
  height = 104,
  label,
  className,
}: {
  data: number[]
  format: (v: number) => string
  /** the pointed index, or null; the host owns it and shows its reading */
  hi: number | null
  onHi: (i: number | null) => void
  /** named levels: a hairline across the plot, the figure and name on the right axis */
  levels?: ScrubLineLevel[]
  /** indices that get a dot on the line */
  marks?: number[]
  /** a name per point along the bottom axis; null leaves a point unnamed */
  axis?: (string | null)[]
  stroke?: string
  /** a soft fill under the line */
  fill?: boolean
  height?: number
  /** names the chart to a screen reader; without it the chart is decoration */
  label?: string
  className?: string
}) {
  const reduced = useReducedMotion()
  const uid = useId().replace(/:/g, "")
  const box = useRef<HTMLSpanElement>(null)
  /* the plot's real width: its layout width, which a transform on the way in does not change */
  const [w, setW] = useState(0)
  useLayoutEffect(() => {
    const el = box.current
    if (!el) return
    const read = () => setW(el.offsetWidth)
    read()
    if (typeof ResizeObserver === "undefined") return
    const ro = new ResizeObserver(read)
    ro.observe(el)
    return () => ro.disconnect()
  }, [])

  const series = data.length ? data : [0]
  const last = series.length - 1
  const max = Math.max(...series)
  const min = Math.min(...series)
  const span = Math.max(1e-9, max - min)
  const x = (i: number) => SIDE + (i / Math.max(1, last)) * Math.max(0, w - SIDE * 2)
  const y = (v: number) => TOP + (1 - (clamp(v, min, max) - min) / span) * (height - TOP - BOT)
  const line = series.map((v, i) => `${i === 0 ? "M" : "L"} ${x(i).toFixed(1)} ${y(v).toFixed(1)}`).join(" ")
  const area = `${line} L ${x(last).toFixed(1)} ${height} L ${x(0).toFixed(1)} ${height} Z`

  /* the axis figures, each at its level, pushed apart where two levels sit close */
  const placed = levels.map((l) => ({ ...l, y: y(l.value), at: y(l.value) })).sort((a, b) => a.y - b.y)
  placed.forEach((l, i) => {
    l.at = Math.max(l.at, i ? placed[i - 1].at + LEVEL_GAP : 5)
  })
  for (let i = placed.length - 1; i >= 0; i--) {
    placed[i].at = Math.min(placed[i].at, i === placed.length - 1 ? height - 5 : placed[i + 1].at - LEVEL_GAP)
  }
  const widest = placed.reduce((a, l) => (`${format(l.value)} ${l.name}`.length > a.length ? `${format(l.value)} ${l.name}` : a), "")

  /* the bottom axis: as many names as the width holds, evenly through the series, ends kept */
  const named = (axis ?? []).map((t, i) => (t == null || i > last ? -1 : i)).filter((i) => i >= 0)
  const room = Math.max(2, Math.floor(w / TICK_ROOM) + 1)
  const ticks =
    named.length <= room ? named : [...new Set(Array.from({ length: room }, (_, k) => named[Math.round((k * (named.length - 1)) / (room - 1))]))]

  const onMove = (e: PointerEvent<HTMLSpanElement>) => {
    if (!w) return
    const r = e.currentTarget.getBoundingClientRect()
    const px = ((e.clientX - r.left) / (r.width || 1)) * w
    onHi(clamp(Math.round(((px - SIDE) / Math.max(1, w - SIDE * 2)) * last), 0, last))
  }
  const at = hi === null ? null : clamp(hi, 0, last)

  return (
    <span className={cn("grid grid-cols-[minmax(0,1fr)_auto] gap-x-2.5", className)}>
      <span ref={box} className="relative block cursor-crosshair touch-none" style={{ height }} onPointerMove={onMove} onPointerLeave={() => onHi(null)}>
        {w > 0 && (
          <svg
            width={w}
            height={height}
            viewBox={`0 0 ${w} ${height}`}
            className="absolute inset-0 block overflow-visible"
            fill="none"
            role={label ? "img" : undefined}
            aria-label={label}
            aria-hidden={label ? undefined : true}
          >
            {fill && (
              <>
                <defs>
                  <linearGradient id={`scrub-${uid}`} x1="0" y1="0" x2="0" y2="1">
                    <stop offset="0%" stopColor={stroke} stopOpacity="0.1" />
                    <stop offset="100%" stopColor={stroke} stopOpacity="0" />
                  </linearGradient>
                </defs>
                <motion.path
                  d={area}
                  fill={`url(#scrub-${uid})`}
                  initial={reduced ? false : { opacity: 0 }}
                  animate={{ opacity: 1 }}
                  transition={{ duration: 0.3, ease: EASE, delay: 0.2 }}
                />
              </>
            )}
            {placed.map((l) => (
              <line
                key={l.name}
                x1={0}
                x2={w}
                y1={l.y}
                y2={l.y}
                stroke="var(--foreground)"
                strokeOpacity={l.guide ? 0.28 : 0.05}
                strokeWidth={1}
                strokeDasharray={l.guide ? "2 4" : undefined}
              />
            ))}
            <motion.path
              d={line}
              stroke={stroke}
              strokeWidth={1.8}
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeOpacity={at === null ? 0.9 : 0.45}
              style={{ transition: reduced ? "none" : "stroke-opacity 150ms" }}
              initial={{ pathLength: reduced ? 1 : 0 }}
              animate={{ pathLength: 1 }}
              transition={reduced ? { duration: 0 } : { duration: 0.5, ease: EASE }}
            />
            {marks.map((m) =>
              m >= 0 && m <= last ? (
                <motion.circle
                  key={m}
                  cx={x(m)}
                  cy={y(series[m])}
                  r={2.4}
                  fill={stroke}
                  initial={reduced ? false : { opacity: 0 }}
                  animate={{ opacity: 1 }}
                  transition={{ duration: 0.2, ease: EASE, delay: 0.3 }}
                />
              ) : null,
            )}
            {at !== null && (
              <g pointerEvents="none">
                <line x1={x(at)} x2={x(at)} y1={0} y2={height} stroke="var(--foreground)" strokeOpacity={0.16} strokeWidth={1} />
                <circle cx={x(at)} cy={y(series[at])} r={3} fill={stroke} />
              </g>
            )}
          </svg>
        )}
      </span>
      {placed.length > 0 && (
        <span aria-hidden className="relative block whitespace-nowrap text-[9px] leading-none" style={{ height }}>
          {/* the widest figure holds the column's width; the figures themselves sit at their levels */}
          <span className="invisible block font-medium">{widest}</span>
          {placed.map((l) => (
            <span key={l.name} className="absolute left-0 -translate-y-1/2" style={{ top: l.at }}>
              <span className="font-medium text-foreground/90">{format(l.value)}</span> <span className="text-foreground/45">{l.name}</span>
            </span>
          ))}
        </span>
      )}
      {ticks.length > 0 && (
        <span aria-hidden className="relative col-start-1 mt-1.5 block h-[11px] whitespace-nowrap text-[9px] leading-[11px] text-foreground/45">
          {w > 0 &&
            ticks.map((i) => (
              <span
                key={i}
                className={cn("absolute top-0", i === 0 ? "translate-x-0" : i === last ? "-translate-x-full" : "-translate-x-1/2")}
                style={{ left: i === 0 ? 0 : i === last ? w : x(i) }}
              >
                {axis?.[i]}
              </span>
            ))}
        </span>
      )}
    </span>
  )
}

